// SHA-256 over UTF-8 bytes. Artifact integrity only; it does not authenticate records.
const primes=[];for(let n=2;primes.length<64;n++)if(!primes.some(p=>n%p===0))primes.push(n);
const K=primes.map(p=>(Math.cbrt(p)%1*4294967296)>>>0),IV=primes.slice(0,8).map(p=>(Math.sqrt(p)%1*4294967296)>>>0),rotr=(x,n)=>(x>>>n)|(x<<(32-n));
export function sha256(text){const input=typeof text==='string'?new TextEncoder().encode(text):text,length=input.length,padded=new Uint8Array(Math.ceil((length+9)/64)*64);padded.set(input);padded[length]=128;const view=new DataView(padded.buffer);view.setUint32(padded.length-8,Math.floor(length*8/4294967296));view.setUint32(padded.length-4,length*8>>>0);const h=[...IV],w=new Uint32Array(64);
 for(let offset=0;offset<padded.length;offset+=64){for(let i=0;i<16;i++)w[i]=view.getUint32(offset+4*i);for(let i=16;i<64;i++){const a=w[i-15],b=w[i-2],s0=rotr(a,7)^rotr(a,18)^(a>>>3),s1=rotr(b,17)^rotr(b,19)^(b>>>10);w[i]=(w[i-16]+s0+w[i-7]+s1)>>>0;}let[a,b,c,d,e,f,g,j]=h;for(let i=0;i<64;i++){const s1=rotr(e,6)^rotr(e,11)^rotr(e,25),choice=(e&f)^(~e&g),t1=(j+s1+choice+K[i]+w[i])>>>0,s0=rotr(a,2)^rotr(a,13)^rotr(a,22),majority=(a&b)^(a&c)^(b&c),t2=(s0+majority)>>>0;j=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=b;b=a;a=(t1+t2)>>>0;}const values=[a,b,c,d,e,f,g,j];for(let i=0;i<8;i++)h[i]=(h[i]+values[i])>>>0;}
 return h.map(n=>n.toString(16).padStart(8,'0')).join('');}
export function canonical(x){if(Array.isArray(x))return '['+x.map(canonical).join(',')+']';if(x&&typeof x==='object')return '{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+canonical(x[k])).join(',')+'}';return JSON.stringify(x);}
